parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const type = body.type || 'subscriber';
const now = new Date().toISOString();

return [{
  json: {
    type,
    name: body.name || '',
    email: body.email || '',
    subject: body.subject || (type === 'subscriber' ? 'New DFN Movement Signup' : ''),
    message: body.message || '',
    enquiryType: body.type === 'contact' ? (body.type || 'general') : '',
    source: body.source || 'website',
    site: body.site || 'dfnworldwide.com',
    timestamp: body.timestamp || now,
  }
}];

parameters.text:
=New contact form submission on dfnworldwide.com

Type: {{ $json.enquiryType }}
